fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    // First find the larger and smaller between indices i and j
    let (mut max1, mut max2) = if valores[i] >= valores[j] {
        (i, j)
    } else {
        (j, i)
    };

    // Now insert k into the top two if applicable
    if valores[k] >= valores[max1] {
        // k is the new maximum, push down the old max1
        (k, max1)
    } else if valores[k] >= valores[max2] {
        // k is between max1 and max2
        (max1, k)
    } else {
        // k is the smallest of the three
        (max1, max2)
    }
}

